type Command =
  | { type: 'reserve-stock'; orderId: string; qty: number }
  | { type: 'cancel-order'; orderId: string };

function handle(command: Command): void {
  switch (command.type) {
    case 'reserve-stock': stock.reserve(command.orderId, command.qty); break;
    case 'cancel-order': stock.cancel(command.orderId); break;
    default: { const unhandled: never = command; throw new Error(`unhandled ${unhandled}`); }
  }
}
